"""Interactive .env writer. API-key input is hidden and never printed."""
from __future__ import annotations

import getpass
import os
import sys
from pathlib import Path

ENV_PATH = Path(__file__).resolve().parent / ".env"
DEFAULT_MODEL = "euri-auto"
DEFAULT_BASE_URL = "https://api.euron.one/api/v1/euri"

TEMPLATE = """# Meridian Retail support-draft review tool
# Generated by setup_env.py. Do not commit this file.
APP_EURI_API_KEY={api_key}
APP_EURI_MODEL={model}
APP_EURI_BASE_URL={base_url}
"""


def write_env(api_key: str, model: str = DEFAULT_MODEL,
              base_url: str = DEFAULT_BASE_URL, path: Path | None = None) -> Path:
    """Write .env atomically and return its path. Reject blank or multiline values."""
    key = (api_key or "").strip()
    if not key:
        raise ValueError("APP_EURI_API_KEY cannot be empty.")
    values = {
        "APP_EURI_API_KEY": key,
        "APP_EURI_MODEL": (model or DEFAULT_MODEL).strip() or DEFAULT_MODEL,
        "APP_EURI_BASE_URL": (base_url or DEFAULT_BASE_URL).strip() or DEFAULT_BASE_URL,
    }
    if any("\n" in value or "\r" in value for value in values.values()):
        raise ValueError("Environment values must be single-line.")
    target = Path(path) if path else ENV_PATH
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_name(target.name + ".tmp")
    try:
        temporary.write_text(TEMPLATE.format(api_key=values["APP_EURI_API_KEY"], model=values["APP_EURI_MODEL"], base_url=values["APP_EURI_BASE_URL"]), encoding="utf-8")
        try:
            temporary.chmod(0o600)
        except OSError:
            pass
        temporary.replace(target)
    finally:
        if temporary.exists():
            temporary.unlink()
    return target


def prompt_for_values() -> tuple[str, str, str]:
    api_key = getpass.getpass("Euri API key (hidden): ").strip()
    model = input(f"Model [{DEFAULT_MODEL}]: ").strip() or DEFAULT_MODEL
    base_url = input(f"Base URL [{DEFAULT_BASE_URL}]: ").strip() or DEFAULT_BASE_URL
    return api_key, model, base_url


def main() -> int:
    try:
        api_key, model, base_url = prompt_for_values()
        path = write_env(api_key, model, base_url)
    except (ValueError, KeyboardInterrupt, OSError) as exc:
        print(f"setup_env: {exc or 'cancelled'}", file=sys.stderr)
        return 1
    print(f"Wrote {path.name} ({os.path.relpath(path)})")
    print("Run: python app.py --case C1 --offline-demo")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
